import {regionSelection,worldHTML,threatHTML} from './campaign-ui.js';
import {SECTORS,UPGRADES,binary,freshState,validateSave,subnet,challenge,checkAnswer,award,canUnlock,restored,LAYERS,learningSupport,SITE_COMPONENTS,WORKSTATION_REWARDS,availableModules,nextTerminal,openSector,canStartUplink,startUplink,chooseRegion,regionFor,regionControl,worldControl,signalReward,registerMistake,scrambleTrace} from './engine.js';
import {TERMINAL_CASES} from './terminal.js';
import {renderTerminalPanel} from './terminal-ui.js';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY='bitforge-save-v1';let state=freshState(),saveError=false;
try{const saved=localStorage.getItem(KEY);if(saved)state=validateSave(JSON.parse(saved));}catch(e){saveError=true;}
let view='network',q=null,bits=0,choice='',solved=false,misses=0,helped=false,finalMode=false,rush=null,canvas=null,selectedRelay=0,lastFrame=0,revealed=false,audioCtx,wrongValues=new Set();

const has=id=>state.upgrades.includes(id),countRestored=()=>Array.from({length:24},(_,i)=>restored(state,i)).filter(Boolean).length;
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));$('#saveStatus').textContent='Saved on this device · export a save to take it with you';saveError=false;}catch(e){$('#saveStatus').textContent='Browser saving unavailable · export your save before leaving';saveError=true;}}
function tone(success=true){if(!state.settings.sound)return;try{audioCtx??=new(window.AudioContext||window.webkitAudioContext)();audioCtx.resume();const o=audioCtx.createOscillator(),g=audioCtx.createGain();o.connect(g);g.connect(audioCtx.destination);o.frequency.setValueAtTime(success?440:180,audioCtx.currentTime);o.frequency.exponentialRampToValueAtTime(success?880:130,audioCtx.currentTime+.13);g.gain.setValueAtTime(.06,audioCtx.currentTime);g.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+.22);o.start();o.stop(audioCtx.currentTime+.23);}catch(e){}}
function toast(text){const e=document.createElement('div');e.className='toast';e.textContent=text;$('#toasts').append(e);setTimeout(()=>e.remove(),4200);}
function modal(html){$('#modalBody').innerHTML=html;if(!$('#modal').open)$('#modal').showModal();}
$('#closeModal').onclick=()=>$('#modal').close();$('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))$('#modal').close();});
function updateHud(){$('#energy').textContent=Math.floor(state.energy).toLocaleString();$('#shards').textContent=state.shards;$('#modules').textContent=availableModules(state);const level=Math.floor(state.xp/150)+1;$('#rank').textContent=`LEVEL ${level} · ${state.won?'ARCHITECT':level>9?'ENGINEER':level>4?'BUILDER':'APPRENTICE'}`;$('#xpbar').style.width=(state.xp%150)/1.5+'%';$('#researchBadge').textContent=state.shards?'· '+state.shards:'';document.body.classList.toggle('reduce-motion',!state.settings.motion);}
function nextQuestion(){q=challenge(finalMode?state.finalStep:state.sector,finalMode?8+state.finalStep:state.counts[state.sector]);bits=0;choice='';solved=false;misses=0;helped=false;revealed=false;wrongValues.clear();}
function render(){updateHud();$$('nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===view));canvas=null;if(!state.region){renderOrigin();return;}({network:renderNetwork,research:renderResearch,terminal:renderTerminal,guide:renderGuide,classroom:renderClassroom})[view]();}
$$('nav button').forEach(b=>b.onclick=()=>{if(rush&&view!==b.dataset.view){toast('Finish or end your sprint before switching views.');return;}view=b.dataset.view;render();});$('.brand').onclick=e=>{e.preventDefault();view='network';render();};
function renderNetwork(){if(!q)nextQuestion();const s=SECTORS[state.sector],all=state.counts.every(n=>n>=8);$('#view').innerHTML=`${state.won?'<div class="victory"><b>The free network is online. You are a Network Architect.</b> Recover stranded servers in the terminal or set a new recovery sprint record.</div>':''}${workstationMission()}<div class="game-layout"><div><div id="campaignWorld">${worldHTML(state,finalMode?q.sector:state.sector)}</div><section class="panel local-sectors"><div class="sector-grid">${SECTORS.map((sec,i)=>`<button class="sector-btn ${state.sector===i?'selected':''} ${!state.unlocked.includes(i)?'locked':''}" data-sector="${i}" aria-pressed="${state.sector===i}"><span class="sector-index">SECTOR 0${i+1} ${state.counts[i]>=8?'✓':''}</span><b>${regionFor(state,i).name}</b><small>${state.unlocked.includes(i)?`${Math.min(state.counts[i],8)}/8 signals · ${sec.topic}`:'Locked · '+sec.topic}</small></button>`).join('')}</div></section><section class="panel mission"><div class="mission-icon">${all?'❖':'ϟ'}</div><div><h3>${state.won?'Network liberated':all?'The final uplink':state.counts[state.sector]<6?'Restore this sector':state.counts[state.sector]<8?'Finish the local grid':'Explore the next frontier'}</h3><p>${state.won?'The Overseer has lost these sectors. Stranded servers still need your help.':all?state.terminalCompleted.length<6?'Complete all six workstation recoveries to power the final uplink.':state.installedModules.includes(6)?'Uplink hardware installed. Resume at no extra cost.':'Install one module and 300 components, then complete six final signals.':state.counts[state.sector]<6?`${6-state.counts[state.sector]} more signals to qualify for the next sector. Every 2 restores a relay.`:state.counts[state.sector]<8?'Reach 8 signals to restore all four relays here.':state.sector<5?'Select the next sector to fund its equipment and decode its access routes.':'Restore 8 signals in every sector for the final uplink.'}</p></div>${all&&!state.won&&!finalMode?`<button class="secondary" id="finalBtn" ${canStartUplink(state)?'':'disabled'}>${state.installedModules.includes(6)?'Resume uplink':'Start uplink · 300 components + 1 module'}</button>`:''}</section><div class="row" style="margin-top:14px"><label class="small muted" for="relaySelect">Inspect relay</label><select id="relaySelect" class="secondary">${Array.from({length:24},(_,i)=>`<option value="${i}" ${i===selectedRelay?'selected':''}>${binary(i,5)} · ${restored(state,i)?'online':'dormant'}</option>`).join('')}</select><span class="small muted" id="relayInfo">${relayInfo()}</span></div></div><div class="combat-column"><div id="threatPanel">${threatHTML(state,finalMode?q.sector:state.sector)}</div><section class="panel challenge" id="challengePanel"></section></div></div>`;
 bindCampaign();canvas=null;$$('[data-sector]').forEach(b=>b.onclick=()=>selectSector(Number(b.dataset.sector)));$('#relaySelect').onchange=e=>{selectedRelay=Number(e.target.value);$('#relayInfo').textContent=relayInfo();};if($('#workstationBtn'))$('#workstationBtn').onclick=()=>{view='terminal';render();};if($('#finalBtn'))$('#finalBtn').onclick=()=>{if(!startUplink(state))return;save();finalMode=true;nextQuestion();render();toast('Final uplink started. Mistakes are safe to retry.');};renderChallenge();}
function renderOrigin(){$('#view').innerHTML=regionSelection(state);$$('[data-start-region]').forEach(b=>b.onclick=()=>{if(!chooseRegion(state,b.dataset.startRegion))return;save();nextQuestion();render();toast('Base established in '+regionFor(state,0).name+'. The resistance begins.');});}
function bindCampaign(){$$('[data-world-sector]').forEach(b=>b.onclick=()=>selectSector(Number(b.dataset.worldSector)));if($('#scrambleBtn'))$('#scrambleBtn').onclick=()=>{if(!scrambleTrace(state,finalMode?q.sector:state.sector))return;save();refreshCampaign();toast('Trace scrambled. Four correct repairs recharge the ability.');};}
function refreshCampaign(){if($('#signalReward'))$('#signalReward').textContent='+'+signalReward(state,q);if(!$('#campaignWorld'))return;const active=finalMode?q.sector:state.sector;$('#campaignWorld').innerHTML=worldHTML(state,active);$('#threatPanel').innerHTML=threatHTML(state,active);bindCampaign();}
function relayInfo(){return `${regionFor(state,Math.floor(selectedRelay/4)).name} · ${restored(state,selectedRelay)?'carrying resistance traffic':'needs '+((selectedRelay%4+1)*2)+' sector signals'}`;}
function workstationMission(){const id=nextTerminal(state);if(id===undefined)return '';const job=TERMINAL_CASES[id];return `<section class="panel mission workstation-mission"><div class="mission-icon">▤</div><div><p class="eyebrow">WORKSTATION DISPATCH · ${id+1}/6</p><h3>${job.title}</h3><p>Recover <b>${job.reward} components + 1 uplink module</b>. ${id<5?'This hardware brings '+regionFor(state,id+1).name+' online.':'This hardware powers the final uplink.'} Signal practice earns intel and spare parts; only the workstation yields modules.</p></div><button class="primary" id="workstationBtn">Enter workstation</button></section>`;}
function selectSector(i){if(rush){toast('End the sprint to change sectors.');return;}if(finalMode){toast('Finish or leave the final uplink first.');return;}if(state.unlocked.includes(i)){state.sector=i;nextQuestion();save();render();return;}const task=TERMINAL_CASES[i-1],done=state.terminalCompleted.includes(i-1);modal(`<p class="eyebrow">BRING A SITE ONLINE</p><h2>${regionFor(state,i).name}</h2><p>${SECTORS[i].story}</p><div class="lesson"><p>${SECTORS[i].lesson}</p></div><ul class="funding-list"><li>${state.jammed[i-1]===0?'✓ Local connection stable':'○ Clear the sentinel jam in '+regionFor(state,i-1).name}</li><li>${state.counts[i-1]>=6?'✓':'○'} 6 signals in ${regionFor(state,i-1).name} (${Math.min(state.counts[i-1],6)}/6)</li><li>${done?'✓':'○'} Workstation recovery: ${task.title}</li><li>${availableModules(state)>0?'✓':'○'} 1 uplink module (${availableModules(state)} available)</li><li>${state.energy>=SITE_COMPONENTS[i]?'✓':'○'} ${SITE_COMPONENTS[i]} components (${state.energy} available)</li><li>${state.shards>=SECTORS[i].cost?'✓':'○'} ${SECTORS[i].cost} intel (${state.shards} available)</li></ul><p class="small muted">Recover working modules in the workstation. They are installed once per new site. Need more components or intel? Keep repairing signals. Sentinel raids temporarily halve signal salvage until two correct repairs clear the jam.</p><div class="row"><button id="unlockSector" class="primary" ${canUnlock(state,i)?'':'disabled'}>Install equipment and open site</button><button id="sectorWorkstation" class="secondary">Enter workstation</button></div>`);$('#sectorWorkstation').onclick=()=>{$('#modal').close();view='terminal';render();};$('#unlockSector').onclick=()=>{if(!openSector(state,i))return;$('#modal').close();nextQuestion();save();render();tone();toast(regionFor(state,i).name+' online. Uplink module installed.');};}
function renderChallenge(){const sec=SECTORS[q.sector];$('#challengePanel').innerHTML=`<div class="challenge-top"><span class="step">${rush?'SIGNAL SPRINT · <b id="rushTime">'+Math.max(0,Math.ceil((rush.end-Date.now())/1000))+'s</b>':finalMode?'FINAL UPLINK · '+(state.finalStep+1)+'/6':'SECTOR 0'+(q.sector+1)+' · '+sec.tag}</span><span class="streak">${rush?rush.score+' signals':state.streak>1?'ϟ '+state.streak+' streak':'Build at your pace'}</span></div><h2>${q.title}</h2><p>${q.prompt}</p><p class="dispatch-note">${q.sector===5?"Resistance command: diagnose this server fault so the recovery team can secure its maintenance cache.":"Resistance command: restore controller access to recover components from a maintenance cache."}</p>${state.counts[q.sector]<2&&!rush?`<div class="lesson"><p>${sec.lesson}</p></div>`:''}<div class="target"><span class="label">${q.label}</span><div class="${q.kind==='bits'&&/^\d+$/.test(q.display)||q.kind==='choice'&&q.sector!==5?'target-number':q.sector===5?'target-incident':'target-code'}">${esc(q.display)}</div></div><div id="answerArea">${q.kind==='bits'?`<p class="small muted">${learningSupport(state,q,revealed)?'Place-value guide on':'Independent repair · place values hidden'}</p><div class="bit-row ${q.width===8?'eight':''}">${Array.from({length:q.width},(_,i)=>{const n=2**(q.width-1-i),on=!!(bits&n);return`<div class="bit-column"><small aria-hidden="true">${learningSupport(state,q,revealed)?n:"·"}</small><button class="bit ${on?'on':''}" data-bit="${n}" aria-label="${learningSupport(state,q,revealed)?"Bit with value "+n:"Bit "+(i+1)+" of "+q.width+" from the left"}" aria-pressed="${on}" ${solved?'disabled':''}>${on?1:0}</button></div>`;}).join('')}</div><div class="sum" id="sum">${sumLabel()}</div>`:q.kind==='choice'?`<div class="options">${q.options.map(o=>`<button class="option ${choice===o?'selected':''}" data-choice="${o}" aria-pressed="${choice===o}" ${solved?'disabled':''}>${o}</button>`).join('')}</div>`:`<label class="answer-label" for="answer">${q.kind==='number'?'Your decimal answer':'Your IPv4 address'}</label><input id="answer" class="input-answer" inputmode="${q.kind==='number'?'numeric':'decimal'}" autocomplete="off" placeholder="${q.kind==='number'?'e.g. 42':'e.g. 192.168.1.0'}" ${solved?'disabled':''}>`}</div><button class="primary" id="submitAnswer">${solved?'Next signal':'Transmit signal'}</button><div class="challenge-actions">${q.kind==='bits'&&!learningSupport(state,q,revealed)?'<button class="ghost" id="revealWeights">Reveal place values</button>':''}<button class="ghost" id="hintBtn">Show a hint</button><button class="ghost" id="lessonBtn">How this works</button></div><div id="feedback" aria-live="polite"></div><div class="row" style="margin:8px 0">${has('overdrive')?`<button class="secondary" id="overBtn" ${state.overCooldown||state.overdrive?'disabled':''}>${state.overdrive?'Priority caches · '+state.overdrive+' left':state.overCooldown?'Next batch · '+state.overCooldown:'Locate larger caches'}</button>`:''}${has('rush')&&!finalMode?`<button class="ghost" id="rushBtn">${rush?'End sprint':'Start 60s sprint'}</button>`:''}${finalMode?'<button class="ghost" id="leaveFinal">Leave uplink</button>':''}</div><div class="reward-line"><span><b id="signalReward">+${signalReward(state,q)}</b> components</span><span><b>+1</b> intel</span><span>${Math.min(state.counts[q.sector],8)}/8 restored</span></div>`;
 $$('[data-bit]').forEach(b=>b.onclick=()=>{if(solved)return;bits^=Number(b.dataset.bit);const on=!!(bits&Number(b.dataset.bit));b.classList.toggle('on',on);b.textContent=on?'1':'0';b.setAttribute('aria-pressed',on);$('#sum').innerHTML=sumLabel();});
 $$('[data-choice]').forEach(b=>b.onclick=()=>{choice=b.dataset.choice;$$('[data-choice]').forEach(x=>{x.classList.toggle('selected',x===b);x.setAttribute('aria-pressed',x===b);});});
 if($('#revealWeights'))$('#revealWeights').onclick=()=>{if(solved)return;helped=true;revealed=true;renderChallenge();};
 $('#submitAnswer').onclick=submit;$('#hintBtn').onclick=()=>{if(solved)return;helped=true;$('#feedback').innerHTML=`<div class="feedback hint">${esc(q.hint)}</div>`;};$('#lessonBtn').onclick=()=>{if(!solved)helped=true;modal(`<p class="eyebrow">FIELD GUIDE · ${sec.topic}</p><h2>${sec.name}</h2><p>${sec.lesson}</p><p>${q.hint}</p><p class="small">No time limit in the campaign. Mistakes raise sentinel trace. Stored components, intel, and learning progress are never removed.</p>`);};
 if($('#answer'))$('#answer').onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();submit();}};
 if($('#overBtn'))$('#overBtn').onclick=()=>{if(state.overdrive||state.overCooldown)return;state.overdrive=5;state.overCooldown=10;save();renderChallenge();toast('Larger caches located. Double components for five tasks.');};
 if($('#rushBtn'))$('#rushBtn').onclick=()=>{if(rush)endRush();else{rush={end:Date.now()+60000,score:0};nextQuestion();renderChallenge();toast('60 seconds. Hints still work. Go!');}};
 if($('#leaveFinal'))$('#leaveFinal').onclick=()=>{finalMode=false;nextQuestion();render();};
 if(solved)$('#feedback').innerHTML=`<div class="feedback">${esc(q.explain)}</div>`;
}
function sumLabel(){if(learningSupport(state,q,revealed)){const terms=Array.from({length:q.width},(_,i)=>2**i).reverse().filter(n=>bits&n);return `${terms.join(' + ')||'All switches off'} = <b>${bits}</b>`;}return 'Read the 1s from left to right. Each on bit adds its place value.';}
function submit(){if(rush&&Date.now()>=rush.end){endRush();return;}if(solved){nextQuestion();render();return;}const value=q.kind==='bits'?bits:q.kind==='choice'?choice:$('#answer').value.trim();if(value===''||value===undefined){$('#feedback').innerHTML='<div class="feedback hint">Enter or choose an answer first.</div>';return;}
 state.attempts[q.sector]++;if(!checkAnswer(q,value)){misses++;state.streak=0;let raid=false;const newError=!wrongValues.has(String(value));if(newError){wrongValues.add(String(value));raid=registerMistake(state,q.sector);}refreshCampaign();if(raid)toast('Sentinel raid! Two correct repairs break the jam.');$('#feedback').innerHTML=`<div class="feedback error"><b>${raid?'Sentinel raid — local link jammed.':newError?(state.won?'Signal rejected. Try again.':state.jammed[q.sector]?'Link remains jammed. Two correct repairs restore it.':'Signal intercepted. Trace increased.'):'Same signal. Recheck the bit values.'}</b><br>${esc(q.hint)}${misses>=2?`<br><button class="ghost" id="revealBtn">Walk me through the answer</button>`:''}</div>`;if($('#revealBtn'))$('#revealBtn').onclick=()=>{helped=true;$('#feedback').innerHTML=`<div class="feedback hint">${esc(q.explain)}<br>Enter it yourself, then transmit to continue.</div>`;};save();tone(false);return;}
 solved=true;const before=countRestored(),controlBefore=regionControl(state,q.sector),wasJammed=state.jammed[q.sector]>0,earned=award(state,q,{first:misses===0,assisted:helped});if(rush)rush.score++;let justWon=false;if(finalMode&&state.jammed[q.sector]===0){state.finalStep++;if(state.finalStep===6){state.won=true;justWon=true;finalMode=false;state.energy+=500;toast('Network restored! +500 components.');}}
 if(countRestored()>before)toast('Relay restored! Resistance traffic can use this link.');if(state.counts[q.sector]===6&&q.sector<5)toast('Signal clearance ready. Recover your workstation module to open '+regionFor(state,q.sector+1).name+'.');badges();save();updateHud();refreshCampaign();tone();if(controlBefore<5&&regionControl(state,q.sector)===5)toast(regionFor(state,q.sector).name+' liberated! Regional sentinel disabled.');
 $$('[data-bit], [data-choice], #answer').forEach(e=>e.disabled=true);$('#submitAnswer').textContent=justWon?'Keep exploring':'Next signal';$('#feedback').innerHTML=`<div class="feedback"><b>${wasJammed?(state.jammed[q.sector]?'Interference weakening. ':'Sentinel jam cleared. '):'Recovery verified. '}+${earned} components · +1 intel</b><br>${esc(q.explain)}</div>`;$('#challengePanel').classList.remove('flash');void $('#challengePanel').offsetWidth;$('#challengePanel').classList.add('flash');if($('#relayCount'))$('#relayCount').textContent=countRestored()+'/24 RELAYS';
 $$('[data-sector]').forEach(b=>{const i=Number(b.dataset.sector);if(state.unlocked.includes(i))b.querySelector('small').textContent=`${Math.min(state.counts[i],8)}/8 signals · ${SECTORS[i].topic}`;});
 if(justWon)modal('<p class="eyebrow">MISSION COMPLETE</p><h2>The network belongs to us again.</h2><p>You learned binary, configured IP networks, and diagnosed faults using the OSI model. The final uplink is restored.</p><div class="stat-grid"><div class="stat-box"><b>24</b><span>relays restored</span></div><div class="stat-box"><b>6</b><span>sectors connected</span></div><div class="stat-box"><b>500</b><span>bonus components</span></div></div><p>Keep exploring. Try the server-recovery missions or beat your sprint record.</p>');
}
function endRush(){if(!rush)return;const n=rush.score;state.bestRush=Math.max(n,state.bestRush);rush=null;badges();save();nextQuestion();render();modal(`<p class="eyebrow">SIGNAL SPRINT COMPLETE</p><h2>${n} signals in this run.</h2><p>Personal best: ${state.bestRush}. Every correct signal counted toward your campaign.</p><p>Take a breath. There is no timer in the regular campaign.</p>`);}
const BADGES=[['spark','First spark','Complete your first repair.',()=>state.total>=1],['streak','In the zone','Solve 5 signals in a row on the first try.',()=>state.bestStreak>=5],['byte','Byte builder','Restore all Cache district relays.',()=>state.counts[1]>=8],['desk','Recovery specialist','Complete three terminal recovery missions.',()=>state.terminalCompleted.length>=3],['network','Network architect','Complete the final uplink.',()=>state.won],['sprint','Quick thinker','Solve 10 signals in one sprint.',()=>state.bestRush>=10]];
function badges(){for(const[id,name,,test]of BADGES)if(!state.badges.includes(id)&&test()){state.badges.push(id);toast('Achievement: '+name);}}
function upgradeReason(u){if(u.needs.some(n=>!has(n)))return 'Requires '+u.needs.filter(n=>!has(n)).map(n=>UPGRADES.find(v=>v.id===n).name).join(', ');if(u.sector&&!state.unlocked.includes(u.sector))return 'Requires '+SECTORS[u.sector].name;return '';}
function renderResearch(){$('#view').innerHTML=`<div class="section-intro"><div><p class="eyebrow">GROW YOUR POSSIBILITIES</p><h2>Resistance tech tree</h2><p>Verified recovery tasks open maintenance caches and reveal infrastructure intel. Spend components on equipment and intel on tools and access routes. Workstation missions recover the modules needed to bring each new site online.</p></div><span class="chip">${state.shards} intel · ${Math.floor(state.energy)} components</span></div><div class="lesson"><p>Upgrades are optional. Reserve components and intel for your next site, or earn more by practicing. Uplink modules can only be spent on the campaign, so upgrades cannot consume them.</p></div><div class="tree-grid">${['01 / RECOVERY TOOLS','02 / YOUR RESISTANCE CONSOLE'].map((branch,i)=>`<div class="tree-col"><h3>${branch}</h3>${UPGRADES.filter(u=>u.branch===i).map(u=>`<section class="panel upgrade ${has(u.id)?'owned':''}"><div class="glyph">${u.icon}</div><h3>${u.name}</h3><p>${u.desc}</p><div class="require">${has(u.id)?'Unlocked ✓':upgradeReason(u)||'Ready to unlock'}</div><button class="secondary" data-upgrade="${u.id}" ${has(u.id)||upgradeReason(u)||(state.shards<u.cost||state.energy<u.credits)?'disabled':''}>${has(u.id)?'Installed':`Unlock · ${u.cost} ◇ + ${u.credits} components`}</button></section>`).join('')}</div>`).join('')}</div>`;$$('[data-upgrade]').forEach(b=>b.onclick=()=>{const u=UPGRADES.find(x=>x.id===b.dataset.upgrade);if(has(u.id)||upgradeReason(u)||state.shards<u.cost||state.energy<u.credits)return;state.shards-=u.cost;state.energy-=u.credits;state.upgrades.push(u.id);save();render();tone();toast(u.name+' unlocked!');});}
function renderTerminal(){renderTerminalPanel({preferNext:true,state,save,toast,badges,updateHud,esc,onNetwork:()=>{view="network";render();}});}
function renderGuide(){$('#view').innerHTML=`<div class="section-intro"><div><p class="eyebrow">RESISTANCE FIELD MANUAL</p><h2>Field guide</h2><p>Learn with support, then work from memory. Help is always available when you need it.</p></div></div><div class="two-col"><section class="panel pad"><h3>Take back the world</h3><p>Choose a starting base with a permanent advantage. Each region has four relay objectives and one workstation server. Free all five to liberate it. World control measures those 30 network objectives, not land area.</p><p>Each different wrong answer raises trace by one; repeating the identical wrong signal does not raise it again. At the trace limit a sentinel jams one objective. Correct repairs still count, but salvage is halved until two repairs clear the jam. Further mistakes cannot stack more jam. Hints and reading never trigger attacks.</p><p>Scramble trace removes two points before a raid; four correct repairs recharge it. No real-time raids occur. The final uplink pauses its stage advancement while its current link remains jammed.</p><h3>From a bit to a service</h3>${SECTORS.map((s,i)=>`<details ${i===state.sector?'open':''}><summary>0${i+1} · ${s.topic}</summary><p>${s.lesson}</p><p>${['0101 = 4 + 1 = 5. Leading zeros preserve the width without changing the value.','10101010 = 128 + 32 + 8 + 2 = 170. Eight bits have 256 patterns, representing 0–255.','192.168.1.10 = 11000000.10101000.00000001.00001010. Four octets make 32 bits.','/27 means 27 network bits and 5 host bits. Its last mask octet is 11100000 = 224.','192.168.1.77/26 is in the 64–127 block. Network .64, broadcast .127, usable .65–.126.','Use the layer’s function to diagnose the problem. Broken cable: Physical. Wrong IP route: Network. HTTP service error: Application.'][i]}</p></details>`).join('')}<details open><summary>Where the rewards come from</summary><p>The Overseer’s takeover left human-run servers disconnected. Each verified recovery task restores access to a controller or server. Your team secures components from its maintenance cache and extracts intel about the captured network.</p><p>Components rebuild equipment at the next site and improve your recovery tools. Intel maps access routes and buys optional tools. Workstation missions unlock for free, one per sector, after the previous recovery. Each pays a large component cache and one working uplink module. Each new site consumes one module; the final uplink needs all six recoveries, 300 components, and one last module. Replays cannot duplicate rewards. Signal practice always earns more parts and intel if you spend too much.</p><p>The network is infrastructure to reclaim. Components come from physical caches, and the animated dots represent resistance packets traveling across restored links.</p></details><details><summary>When the binary labels disappear</summary><p>The first four repairs in each of the first two regions show place values and the current decimal total. After that, labels and live totals disappear. IP and mask work starts without them.</p><p>Use Reveal place values to bring them back for the current question. That solve is recorded as assisted, but pays the same cache. A new question removes the temporary help. Hidden labels also stay hidden from screen-reader names.</p></details></section><section class="panel pad"><h3>The OSI stack</h3><div class="osi-stack">${LAYERS.map((l,i)=>`<div><b>${i+1}</b><span><strong>${l.name}</strong><small>${l.job}</small></span></div>`).reverse().join('')}</div><p class="small muted">OSI is a reference model. Real protocols do not always map neatly to one layer, particularly the top three. These exercises teach the model’s responsibilities.</p><details><summary>Subnet pocket chart</summary><table><thead><tr><th>Prefix</th><th>Mask</th><th>Total</th><th>Usable</th></tr></thead><tbody>${[24,25,26,27,28,29,30].map(p=>{const s=subnet(0,p);return`<tr><td>/${p}</td><td>255.255.255.${s.mask}</td><td>${s.size}</td><td>${s.hosts}</td></tr>`;}).join('')}</tbody></table><p>/31 point-to-point links and /32 routes use different rules. This campaign covers /24–/30 inside a /24.</p></details><details><summary>Controls and progression</summary><p>Every two repairs restores one relay. Six qualifies you for the next sector; eight completes the sector. Recover all six workstation caches and restore all 24 relays, then install the final uplink equipment and finish its six tasks.</p><p>Use Tab and Space for buttons, Enter for typed answers, and the terminal’s Up/Down keys for command history. There is no timer outside optional sprints.</p></details><details><summary>Learning sources</summary><p><a href="https://www.ciscopress.com/articles/article.asp?p=3131360&seqNum=6" target="_blank" rel="noopener">Cisco Press: communication models and OSI responsibilities</a></p><p><a href="https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/windows-commands" target="_blank" rel="noopener">Microsoft: Windows command reference</a></p><p><a href="https://www.cisco.com/c/en/us/support/docs/ip/routing-information-protocol-rip/13790-8.html" target="_blank" rel="noopener">Cisco: host and subnet quantities</a></p></details></section></div>`;}

function renderClassroom(){const attempts=state.attempts.reduce((a,b)=>a+b,0),first=state.firstTry.reduce((a,b)=>a+b,0);$('#view').innerHTML=`<div class="section-intro"><div><p class="eyebrow">A RECORD OF YOUR DISCOVERIES</p><h2>Learning log</h2><p>This device’s progress only. Export the learning report to share with your teacher. Learning progress stays in your browser; the game does not upload it.</p></div><button class="secondary" id="reportBtn">Export learning report</button></div><div class="stat-grid"><div class="stat-box"><b>${state.total}</b><span>signals completed</span></div><div class="stat-box"><b>${state.total?Math.round(first/state.total*100):0}%</b><span>unassisted first-try solves</span></div><div class="stat-box"><b>${state.bestStreak}</b><span>best first-try streak</span></div></div><section class="panel pad" style="overflow:auto"><table><thead><tr><th>Skill</th><th>Completed</th><th>First try, no hint</th><th>Attempts</th><th>Relays</th></tr></thead><tbody>${SECTORS.map((s,i)=>`<tr><td>${s.topic}</td><td>${state.counts[i]}</td><td>${state.firstTry[i]}</td><td>${state.attempts[i]}</td><td>${Math.min(4,Math.floor(state.counts[i]/2))}/4</td></tr>`).join('')}</tbody></table><p class="small muted">${attempts} total attempts · ${state.assisted} solves used a hint or walkthrough. ${state.terminalCompleted.length}/6 terminal work orders completed. Progress measures practice, not a proctored assessment.</p></section><div class="achievement-grid">${BADGES.map(([id,name,desc])=>`<div class="achievement ${state.badges.includes(id)?'earned':''}"><b>${state.badges.includes(id)?'✓':'◇'} ${name}</b>${desc}</div>`).join('')}</div><details><summary>Teacher notes · using Bitforge in a lesson</summary><p>Start with 5 minutes of prediction: what do students think each switch does? Allow 15–20 minutes of exploration and compare binary strategies. Later sessions introduce IP octets, subnet masks, and OSI troubleshooting.</p><p>Ask students to explain why 11111111 equals 255; why a /26 has 64 total addresses but 62 usable hosts; and why ping can succeed when a web service fails. The campaign needs eight signals in each of six sectors, all six workstation recoveries, and a six-signal final uplink.</p><p>Export saves between devices. A shared browser has one save, so export and reset between students. Reports are practice evidence, not an authenticated gradebook. The six-sector campaign includes OSI incident diagnosis. Class pacing will vary.</p></details>`;$('#reportBtn').onclick=()=>{const rows=[['Bitforge learning report'],['Generated',new Date().toISOString()],['Campaign',state.won?'Complete':'In progress'],['Skill','Completed','Unassisted first try','Attempts','Restored relays'],...SECTORS.map((s,i)=>[s.topic,state.counts[i],state.firstTry[i],state.attempts[i],Math.min(4,Math.floor(state.counts[i]/2))]),['Hint-assisted solves',state.assisted],['Best sprint',state.bestRush],['Terminal cases completed',state.terminalCompleted.length],['Note','Local practice evidence; not an authenticated assessment.']];download('bitforge-learning-report.csv',rows.map(r=>r.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(',')).join('\r\n'),'text/csv');};}
function download(name,text,type){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);}
$('#settingsBtn').onclick=()=>{modal(`<p class="eyebrow">MAKE YOURSELF AT HOME</p><h2>Settings & saves</h2><label class="toggle-row">Sound effects<input type="checkbox" id="soundSetting" ${state.settings.sound?'checked':''}></label><label class="toggle-row">Animated network<input type="checkbox" id="motionSetting" ${state.settings.motion?'checked':''}></label><p class="small" style="margin-top:18px">Progress saves on this browser. Export a file to continue on another device. Import replaces this browser’s progress.</p><div class="row"><button class="secondary" id="exportSave">Export save</button><button class="secondary" id="importSave">Import save</button><input type="file" id="saveFile" accept=".json,application/json" hidden></div><p id="importStatus" class="small" role="status"></p><hr style="border:0;border-top:1px solid var(--line);margin:22px 0"><button class="secondary danger" id="resetBtn">Reset this browser’s progress</button>`);$('#soundSetting').onchange=e=>{state.settings.sound=e.target.checked;save();tone();};$('#motionSetting').onchange=e=>{state.settings.motion=e.target.checked;save();updateHud();};$('#exportSave').onclick=()=>download('bitforge-save.json',JSON.stringify(state,null,2),'application/json');$('#importSave').onclick=()=>$('#saveFile').click();$('#saveFile').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>100000)throw Error('Choose a Bitforge save smaller than 100 KB.');const incoming=validateSave(JSON.parse(await file.text()));modal('<h2>Replace this device’s save?</h2><p>The imported save replaces your current progress. Export it first if you want to keep it.</p><div class="row"><button id="backupCurrent" class="secondary">Export current save</button><button id="confirmImport" class="primary">Replace with imported save</button></div>');$('#backupCurrent').onclick=()=>download('bitforge-backup.json',JSON.stringify(state),'application/json');$('#confirmImport').onclick=()=>{state=incoming;finalMode=false;rush=null;nextQuestion();save();$('#modal').close();render();toast('Save imported. Welcome back.');};}catch(err){$('#importStatus').textContent='Could not import: '+err.message;}};$('#resetBtn').onclick=()=>{modal('<h2>Start a fresh network?</h2><p>This removes progress from this browser. Export a save first if you want to return to it.</p><button id="confirmReset" class="secondary danger">Yes, reset all progress</button>');$('#confirmReset').onclick=()=>{state=freshState();finalMode=false;rush=null;view='network';nextQuestion();save();$('#modal').close();render();toast('A fresh network awaits.');};};};
function frame(t){if(t-lastFrame>32){if(rush){if(Date.now()>=rush.end)endRush();else if($('#rushTime'))$('#rushTime').textContent=Math.ceil((rush.end-Date.now())/1000)+'s';}lastFrame=t;}requestAnimationFrame(frame);}
document.addEventListener('visibilitychange',()=>{if(document.hidden){save();if(rush)endRush();}});window.addEventListener('beforeunload',save);nextQuestion();render();if(saveError)$('#saveStatus').textContent='Save could not be loaded · export your progress before leaving';requestAnimationFrame(frame);if(state.migrated||state.economyMigrated){delete state.migrated;delete state.economyMigrated;save();toast('Progress kept. Workstation casebooks are now free; purchased casebooks refunded. Completed recoveries include a module.');}
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'read_bitforge_progress',title:'Read Bitforge progress',description:'Read local campaign progress and the active skill without revealing challenge answers.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:(input)=>{if(!input||typeof input!=='object'||Array.isArray(input)||Object.keys(input).length)throw Error('Expected an empty object.');return {sector:SECTORS[state.sector].name,signals:state.total,relays:countRestored(),complete:state.won,skills:SECTORS.map((s,i)=>({skill:s.topic,completed:state.counts[i]}))};}})).catch(()=>{});}catch(e){}}
